import{_ as n,C as e,o as s,c as d,E as a,a7 as c}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"Personix Privacy Policy","description":"Privacy Policy for Personix, presented within Policy Hub.","frontmatter":{"title":"Personix Privacy Policy","description":"Privacy Policy for Personix, presented within Policy Hub."},"headers":[],"relativePath":"apps/personix/privacy.md","filePath":"apps/personix/privacy.md"}'),l={name:"apps/personix/privacy.md"};function p(h,o,u,m,y,b){const i=e("AppBreadcrumbs"),t=e("AppSubnav"),r=e("CopyStandaloneUrl");return s(),d("div",null,[a(i,{"app-id":"personix",current:"Privacy Policy"}),a(t,{"app-id":"personix"}),a(r,{path:"/privacy/personix",label:"Copy Play Store URL","copied-label":"Play Store URL copied","document-name":"Personix privacy policy"}),o[0]||(o[0]=c('<h1 id="privacy-policy-for-personix" tabindex="-1">Privacy Policy for Personix <a class="header-anchor" href="#privacy-policy-for-personix" aria-label="Permalink to &quot;Privacy Policy for Personix&quot;">​</a></h1><p><strong>Effective Date:</strong> August 3, 2026<br><strong>Last Updated:</strong> August 3, 2026</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Personix is a private, offline-first personal organizer developed by <strong>Anand Raja</strong>. It helps you organize saved links, family and health references, vehicle information, temporary notes, and checklists. Personix does not require an account and does not include advertising, analytics, or developer-operated cloud storage.</p><h2 id="information-stored-on-your-device" tabindex="-1">Information Stored on Your Device <a class="header-anchor" href="#information-stored-on-your-device" aria-label="Permalink to &quot;Information Stored on Your Device&quot;">​</a></h2><p>Personix stores the information you enter locally in SQLite on Android or IndexedDB in a browser. Depending on the features you use, this can include:</p><ul><li>Saved links, titles, descriptions, categories, tags, intended recipients, preview images, and adult-content settings</li><li>Family-member details, contact details, Rasi, Nakshatra, Gothram, hospital OP references, medical-insurance information, medicines, toiletries, and blood-group records</li><li>Vehicle registration, ownership, insurance, pollution-expiry, and note information</li><li>Notes, checklists, and app settings</li></ul><p>This information may be sensitive. Keep your device secured and enter only information you are authorized to store.</p><h2 id="metadata-and-third-party-content" tabindex="-1">Metadata and Third-Party Content <a class="header-anchor" href="#metadata-and-third-party-content" aria-label="Permalink to &quot;Metadata and Third-Party Content&quot;">​</a></h2><p>On Android, Personix can connect directly to a saved website to retrieve Open Graph metadata and preview images. The destination website can receive standard connection information such as your IP address, user agent, request time, and requested URL.</p><p>In the browser version, third-party metadata fetching is disabled by default. If you explicitly enable it, the saved URL is sent to <code>api.microlink.io</code> to retrieve preview information. Microlink&#39;s own privacy terms apply. Embedded or opened content from services such as YouTube, Instagram, Facebook, TikTok, Dailymotion, and Vimeo is handled by those services under their own privacy policies.</p><h2 id="text-based-records-and-backup-files" tabindex="-1">Text-Based Records and Backup Files <a class="header-anchor" href="#text-based-records-and-backup-files" aria-label="Permalink to &quot;Text-Based Records and Backup Files&quot;">​</a></h2><p>Personix records are text-based. The app does not access your camera or collect photo, video, or audio attachments. When you choose to import or export an encrypted backup, the selected backup file is handled through the applicable system file flow. Exported files are controlled by the destination you choose.</p><h2 id="pin-biometrics-and-backups" tabindex="-1">PIN, Biometrics, and Backups <a class="header-anchor" href="#pin-biometrics-and-backups" aria-label="Permalink to &quot;PIN, Biometrics, and Backups&quot;">​</a></h2><p>An optional app PIN is stored as a salted PBKDF2 verifier. On supported Android devices, biometric unlock uses Android&#39;s biometric system and Keystore; Personix does not receive or store your biometric template.</p><p>Backups are encrypted using AES-256-GCM with a key derived from the password you provide. App PINs, biometric credentials, and Android Keystore keys are excluded from backups. Anyone with a backup file and its password may be able to restore its contents, so store both securely.</p><h2 id="information-received-by-the-developer" tabindex="-1">Information Received by the Developer <a class="header-anchor" href="#information-received-by-the-developer" aria-label="Permalink to &quot;Information Received by the Developer&quot;">​</a></h2><p>The developer does not automatically receive your local records, PIN, biometric information, or backup files. If you email support, the developer receives the information you choose to include.</p><h2 id="retention-and-deletion" tabindex="-1">Retention and Deletion <a class="header-anchor" href="#retention-and-deletion" aria-label="Permalink to &quot;Retention and Deletion&quot;">​</a></h2><p>Local information remains until you delete individual records, use the in-app delete-all-data option, clear the app&#39;s storage, clear the browser&#39;s site data, or uninstall the app. Deleting app data does not delete exported backups or files saved or shared elsewhere.</p><h2 id="changes-to-this-policy" tabindex="-1">Changes to This Policy <a class="header-anchor" href="#changes-to-this-policy" aria-label="Permalink to &quot;Changes to This Policy&quot;">​</a></h2><p>This policy may be updated when Personix features or data practices change. The date above will be revised when an updated policy is published.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><ul><li><strong>Developer:</strong> Anand Raja</li><li><strong>Email:</strong> <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></li></ul>',24))])}const P=n(l,[["render",p]]);export{f as __pageData,P as default};
